import Link from "next/link";
import { AppBar, SectionHeader, SiteFooter } from "@/src/components/layout";
import type { NavItem } from "@/src/components/layout";
import { ButtonLink, Card, Icon } from "@/src/components/ui";
import type { IconName } from "@/src/components/ui";
import { EnergyGradeBadge, GradeScale, ProgramCard, ReportMetric } from "@/src/components/domain";
import { getEcoCheckReport } from "@/src/data/account";
import { getGradeDistribution } from "@/src/data/grades";
import { getSupportPrograms } from "@/src/data/programs";
import { formatManwon, formatPercent } from "@/src/lib/format";
import { SearchBar } from "./search/_components/SearchBar";

const NAV_ITEMS: NavItem[] = [
  { label: "홈", href: "/", active: true },
  { label: "에코체크", href: "/eco-check" },
  { label: "지원사업", href: "/programs" },
  { label: "마이페이지", href: "/account" },
];

const POPULAR_QUERIES = ["월드컵로 120", "마포구", "상암"];

interface Step {
  icon: IconName;
  label: string;
  title: string;
  description: string;
}

const STEPS: Step[] = [
  {
    icon: "search",
    label: "STEP 1",
    title: "주소 검색",
    description: "우리 건물의 도로명 주소만 입력하면 바로 검색이 시작돼요.",
  },
  {
    icon: "building",
    label: "STEP 2",
    title: "등급 확인",
    description: "에너지효율등급과 인근 건물 비교 결과를 한눈에 확인하세요.",
  },
  {
    icon: "leaf",
    label: "STEP 3",
    title: "맞춤 혜택 받기",
    description: "난이도별 절감 방법과 신청 가능한 지원사업을 추천받아요.",
  },
];

export default async function Home() {
  const [report, distribution, programs] = await Promise.all([
    getEcoCheckReport(),
    getGradeDistribution(),
    getSupportPrograms(),
  ]);
  const featuredPrograms = programs.slice(0, 3);

  return (
    <div className="flex min-h-dvh flex-col bg-[var(--surface-page)]">
      <AppBar navItems={NAV_ITEMS} cta={{ label: "건물 에너지 확인하기", href: "/search" }} />

      <main className="flex-1">
        {/* Hero */}
        <section className="bg-[var(--surface-brand)]">
          <div className="eco-container flex flex-col items-center gap-[var(--space-8)] py-[var(--space-20)] text-center">
            <span className="inline-flex items-center rounded-[var(--radius-pill)] bg-[var(--teal-800)] px-[var(--space-4)] py-[var(--space-1)] text-[length:var(--text-caption-size)] font-bold text-[var(--teal-50)]">
              무료 건물 에너지 진단
            </span>
            <h1 className="eco-display max-w-2xl text-[var(--text-on-primary)]">
              주소 하나로 확인하는
              <br />
              우리 건물 에너지 등급
            </h1>
            <p className="max-w-xl text-[length:var(--text-body-lg-size)] leading-[var(--text-body-lg-lh)] text-[var(--teal-50)]">
              복잡한 서류 없이 주소만 입력하면 돼요. 에너지효율등급부터 맞춤형 절감 방법, 지원사업까지 한 번에
              확인하세요.
            </p>

            <SearchBar className="max-w-xl" />

            <div className="flex flex-wrap items-center justify-center gap-[var(--space-2)]">
              <span className="text-[length:var(--text-caption-size)] font-bold text-[var(--teal-100)]">
                인기 검색어
              </span>
              {POPULAR_QUERIES.map((query) => (
                <Link
                  key={query}
                  href={`/search?q=${encodeURIComponent(query)}`}
                  className="rounded-[var(--radius-pill)] border border-[var(--teal-500)] bg-[var(--teal-700)] px-[var(--space-4)] py-[var(--space-1)] text-[length:var(--text-caption-size)] font-medium text-[var(--text-on-primary)] transition-colors duration-[var(--dur-fast)] hover:bg-[var(--teal-800)]"
                >
                  {query}
                </Link>
              ))}
            </div>
          </div>
        </section>

        {/* Grade preview */}
        <section className="eco-container py-[var(--space-20)]">
          <SectionHeader
            title="이렇게 리포트를 보여드려요"
            description="주소를 검색하면 우리 건물의 에너지 등급과 절감 잠재력을 이런 리포트로 한눈에 확인할 수 있어요."
          />

          <Card padding="lg" elevation="raised" className="mt-[var(--space-8)]">
            <div className="flex flex-col gap-[var(--space-8)] lg:flex-row lg:items-start lg:justify-between">
              <div className="flex flex-col gap-[var(--space-3)]">
                <span className="text-[length:var(--text-caption-size)] font-bold uppercase tracking-[var(--tracking-wide)] text-[var(--text-link)]">
                  예시 리포트
                </span>
                <div className="flex items-center gap-[var(--space-3)]">
                  <h3 className="eco-heading text-[var(--text-strong)]">{report.buildingName}</h3>
                  <EnergyGradeBadge grade={report.grade} showLabel size="lg" />
                </div>
                <p className="max-w-sm text-[length:var(--text-body-size)] text-[var(--text-muted)]">
                  서울특별시 마포구 월드컵로 120 · 인근 건물 대비 상위 {formatPercent(report.percentileRank)} 수준의
                  에너지 효율이에요.
                </p>
                <ButtonLink href="/search" variant="primary" className="mt-[var(--space-2)] w-fit">
                  내 건물도 확인해보기
                  <Icon name="arrow-right" size={16} />
                </ButtonLink>
              </div>

              <div className="grid w-full grid-cols-1 gap-[var(--gap-card)] sm:grid-cols-3 lg:max-w-lg">
                <ReportMetric label="연간 에너지 비용" value={formatManwon(report.annualEnergyCostManwon)} />
                <ReportMetric
                  label="인근 대비 순위"
                  value={`상위 ${formatPercent(report.percentileRank)}`}
                  tone="good"
                  helpText="인근 건물 비교 기준"
                />
                <ReportMetric
                  label="예상 연간 절감액"
                  value={formatManwon(report.annualSavingsPotentialManwon)}
                  tone="good"
                  helpText="절감 방법 적용 시"
                />
              </div>
            </div>

            <GradeScale distribution={distribution} className="mt-[var(--space-10)]" />
          </Card>
        </section>

        {/* Three steps */}
        <section className="bg-[var(--surface-sunken)] py-[var(--space-20)]">
          <div className="eco-container">
            <SectionHeader
              title="3단계면 충분해요"
              description="복잡한 절차 없이 누구나 쉽게 이용할 수 있어요."
            />

            <ol className="mt-[var(--space-8)] grid grid-cols-1 gap-[var(--gap-card)] sm:grid-cols-3">
              {STEPS.map((step, index) => (
                <li key={step.title}>
                  <Card padding="lg" className="flex h-full flex-col gap-[var(--space-4)]">
                    <div className="flex items-center justify-between">
                      <span
                        aria-hidden="true"
                        className="flex h-11 w-11 items-center justify-center rounded-full bg-[var(--surface-brand-soft)] text-[var(--text-link)]"
                      >
                        <Icon name={step.icon} size={22} />
                      </span>
                      <span aria-hidden="true" className="text-2xl font-black leading-none text-[var(--ink-200)]">
                        {String(index + 1).padStart(2, "0")}
                      </span>
                    </div>
                    <div>
                      <p className="text-[length:var(--text-caption-size)] font-bold uppercase tracking-[var(--tracking-wide)] text-[var(--text-link)]">
                        {step.label}
                      </p>
                      <h3 className="eco-subhead mt-[var(--space-1)] text-[var(--text-strong)]">{step.title}</h3>
                      <p className="mt-[var(--space-2)] text-[length:var(--text-body-size)] text-[var(--text-body)]">
                        {step.description}
                      </p>
                    </div>
                  </Card>
                </li>
              ))}
            </ol>
          </div>
        </section>

        {/* Featured programs */}
        <section className="eco-container py-[var(--space-20)]">
          <SectionHeader
            title="지금 신청할 수 있는 지원사업"
            description="건물 에너지 효율을 높이는 정부·지자체 지원사업을 확인하세요."
            action={{ label: "지원사업 전체 보기", href: "/programs" }}
          />

          <div className="mt-[var(--space-8)] grid grid-cols-1 gap-[var(--gap-card)] sm:grid-cols-2 lg:grid-cols-3">
            {featuredPrograms.map((program) => (
              <ProgramCard key={program.id} program={program} href={`/programs/${program.id}`} />
            ))}
          </div>
        </section>
      </main>

      <SiteFooter />
    </div>
  );
}
